-- Costa Rica deep-dive ES/DE/FR translations, completing 401 against the
-- English content in migration 400. This is a SEPARATE migration file,
-- so every translation row looks up its parent row via a JOIN on stable
-- identifying columns (country name_en / section / sort_order), never
-- via (SELECT MAX(id) ...). INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Clearance en tiempo real mediante el servicio de Recepción de Comprobantes Electrónicos de la DGT -- obligatorio para prácticamente todos los contribuyentes del IVA desde 2018, y actualmente en plena transición hacia la nueva plataforma TRIBU-CR de Hacienda', 'Esta página de análisis refleja la orientación pública de Hacienda/DGT y la información del sector disponible a inicios de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal o tributaria. Confirme los requisitos vigentes directamente con Hacienda, la DGT o un asesor fiscal costarricense antes de basar en esta página sus decisiones de cumplimiento.', 'El régimen de facturación electrónica de Costa Rica se remonta a una primera regulación de 2007 y a un plan piloto voluntario de 2013, se volvió obligatorio para el sector salud y otros servicios profesionales a inicios de 2018, y completó un despliegue general escalonado por dígito de cédula bajo la Resolución DGT-R-012-2018 el 1 de noviembre de 2018. Desde entonces, Hacienda ha seguido haciendo evolucionar el sistema: la versión 4.4 del esquema XML se volvió obligatoria en setiembre de 2025, la plataforma TRIBU-CR sustituyó a ATV en octubre de 2025, y se espera un nuevo cambio en el formato de identificación para noviembre de 2026.', 'Una factura conforme se genera como un documento XML firmado digitalmente y se envía a la API de Recepción de Comprobantes Electrónicos de la DGT. La DGT valida la estructura, los campos y las referencias cruzadas del documento -- en la práctica, normalmente de forma casi instantánea, con un máximo contractual de 3 horas -- y devuelve un estado de aceptado o rechazado antes de que el documento se entregue al receptor. Se trata de un auténtico modelo de clearance: una factura que la DGT no ha aceptado no tiene efecto legal.', 'El mandato ha estado vigente en alguna forma desde 2007, alcanzó a prácticamente todos los contribuyentes del IVA para noviembre de 2018, y sigue evolucionando técnicamente en lugar de ampliar su alcance -- la ola actual de cambios (el esquema v4.4, la plataforma TRIBU-CR, el próximo cambio de formato de cédula) tiene que ver con cómo las empresas ya obligadas transmiten y dan formato a sus facturas, no con quién debe cumplir.', 'La mayoría de las empresas que leen esto probablemente ya están obligadas a emitir Comprobantes Electrónicos -- el trabajo real y actual consiste en mantenerse al día con la transición técnica en curso de Hacienda (esquema v4.4, TRIBU-CR, el cambio de formato de cédula de 2026), no en un despliegue por primera vez.', 'Costa Rica respalda su mandato de facturación electrónica con sanciones reales y específicas por artículo bajo el Código de Normas y Procedimientos Tributarios (CNPT) -- calculadas con base en el salario base fijado judicialmente y no en montos fijos en colones -- y la DGT ha demostrado que realmente las aplica: un solo operativo de 2024 multó a 279 empresas por más de ₡253 millones.', 'Costa Rica exige el clearance en tiempo real por parte de la DGT de los Comprobantes Electrónicos (facturas, tiquetes, notas de crédito/débito y otros) para prácticamente todas las empresas inscritas en el IVA, obligatorio desde 2018. El sistema se encuentra actualmente en plena transición: la versión 4.4 del esquema XML se volvió obligatoria en setiembre de 2025, la nueva plataforma TRIBU-CR de Hacienda sustituyó a ATV en octubre de 2025, y se espera un nuevo cambio hacia la cédula alfanumérica en noviembre de 2026.', '🇨🇷' FROM countries WHERE name_en = 'Costa Rica';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 nov 2018', 'Se completa el mandato general para todos los contribuyentes del IVA restantes' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', 'v4.4', 'Versión vigente y obligatoria del esquema XML, desde el 1 de setiembre de 2025' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '6 oct 2025', 'La nueva plataforma TRIBU-CR de Hacienda sustituye a ATV' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '₡253M+', 'Multados en 279 contribuyentes en un solo operativo de fiscalización de la DGT en 2024' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '≤3 h', 'Tiempo máximo de respuesta de la DGT (SLA) para la validación de facturas' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y validación', '[["Formato de factura", "XML firmado, con esquema propio de Costa Rica (no UBL/PEPPOL)"], ["Modelo de validación", "Clearance -- la DGT debe aceptar el documento antes de que sea fiscalmente válido"], ["Envío", "POST a la API de Recepción de Comprobantes Electrónicos de la DGT (OIDC/OAuth 2.0, XML codificado en base64)"], ["Tiempo de respuesta", "En la práctica, normalmente casi instantáneo; la propia resolución técnica de la DGT fija un máximo de 3 horas"], ["Firma digital", "XAdES EPES v1.3.2 o superior, usando un certificado .p12 emitido por la autoridad certificadora del Banco Central (BCCR)"]]', 'La publicidad de algunos proveedores a veces describe esto como validación puramente "en tiempo real" -- en la práctica suele ser así, pero el SLA vinculante que establece la propia resolución técnica de la DGT es un máximo de 3 horas, no una garantía instantánea.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Tipos de comprobante', '[["01 — Factura Electrónica", "Venta estándar B2B / a comprador identificado"], ["02 / 03 — Nota de Débito / Crédito", "Ajustes, devoluciones, descuentos, anulaciones"], ["04 — Tiquete Electrónico", "Venta al detalle a un consumidor final no identificado (B2C)"], ["08 — Factura Electrónica de Compra", "Comprobante emitido por el comprador al adquirir bienes o servicios de un proveedor informal que no emite facturas"], ["09 — Factura Electrónica de Exportación", "Ventas de exportación con 0% de IVA"]]', 'El Recibo Electrónico de Pago se añadió como un tipo adicional de comprobante con el esquema v4.4 -- confirme que su software lo emite cuando corresponde, en lugar de asumir que los cinco tipos principales anteriores son la lista completa.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Clave numérica, respuesta del receptor y conservación', '[["Clave numérica", "Una clave de 50 dígitos, generada automáticamente por el sistema del emisor, que codifica la fecha de emisión, la identificación del emisor, el tipo de documento, el número consecutivo y un código de seguridad"], ["Respuesta del receptor (B2B)", "El receptor debe aceptar, aceptar parcialmente o rechazar el comprobante dentro de los 8 días hábiles del mes siguiente"], ["Modo contingencia", "Los comprobantes pueden enviarse hasta 48 horas después de restablecerse el servicio si los sistemas de Hacienda están caídos"], ["Conservación", "5 años"]]', 'El desglose exacto, dígito por dígito, de la clave numérica de 50 dígitos varía ligeramente entre fuentes secundarias -- puede confiar en la longitud total (50 dígitos) y el contenido general, pero no se apoye en un desglose posición por posición sin confirmarlo con el anexo técnico vigente de Hacienda.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de clearance', 'Un Comprobante Electrónico conforme recorre esta secuencia:', 'Solo un documento aceptado es un comprobante tributario válido -- una factura que la DGT no ha aceptado no tiene efecto legal, y una que el receptor rechaza de forma correcta no sustenta su deducción.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El emisor genera un XML firmado digitalmente usando un certificado autorizado' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El documento se envía a la API de Recepción de Comprobantes Electrónicos de la DGT' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La DGT valida la estructura, los campos y las referencias cruzadas (en la práctica, casi instantáneo; hasta 3 horas por contrato)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La DGT devuelve un estado de aceptado o rechazado' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El documento aceptado se entrega al receptor, quien debe responder dentro de los 8 días hábiles del mes siguiente' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Lo que exige la ley', '[["DGT-R-012-2018 (2018)", "El mandato general, escalonado por el último dígito de la cédula del contribuyente"], ["Ley 7092 (Ley del Impuesto sobre la Renta), art. 3", "Base legal de la exención limitada para el sector público y las entidades sin fines de lucro"], ["Régimen Simplificado", "Excluido de plano del mandato general"], ["Sin umbral de ingresos", "El mandato es universal para los contribuyentes inscritos en el IVA que no estén dentro de las excepciones señaladas"]]', 'Una vez que un contribuyente entra en el alcance, quedan cubiertas las transacciones B2B, B2C (mediante el Tiquete Electrónico) y B2G -- no se trata de un régimen exclusivo de B2G ni de B2B.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién sigue exento', '[["Contribuyentes del Régimen Simplificado", "Excluidos de plano bajo la DGT-R-012-2018"], ["Entidades del sector público / sin fines de lucro", "Solo para actividad no comercial -- municipalidades, ministerios, universidades públicas, CCSS, Banco Central, Poder Judicial, Asamblea Legislativa"], ["Colegios profesionales", "Solo para el cobro de cuotas de colegiatura"], ["Condominios", "Solo para las cuotas de mantenimiento de áreas comunes"], ["Bancos/cooperativas regulados por la SUGEF y asociaciones solidaristas", "Solo para actividades específicas no gravadas"]]', 'Cualquier ingreso comercial o gravable con IVA que obtengan estas mismas entidades sigue requiriendo facturación electrónica -- la exención es por actividad, no una exoneración general para toda la organización.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ No emitir o entregar una factura conlleva la sanción más alta', NULL, NULL, 'Conforme al artículo 85 del CNPT (Código de Normas y Procedimientos Tributarios), no emitir o no entregar una factura o comprobante electrónico conlleva una multa de 2 salarios base -- aproximadamente ₡924.400 según los valores del salario base de 2024-2025 -- sin descuento por corrección voluntaria disponible para esta infracción en particular. Las multas tributarias costarricenses de este tipo están indexadas al "salario base" fijado judicialmente y no a un monto fijo en colones, por lo que el monto exacto varía según la actualización anual del salario base.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💳 Rechazar pagos electrónicos o alternativos tiene su propia sanción', NULL, NULL, 'El artículo 85 bis del CNPT sanciona por separado el rechazo de medios de pago electrónicos o alternativos (como pagos con tarjeta o SINPE) cuando su aceptación es obligatoria, con una multa de 1 salario base -- aproximadamente ₡462.200 según los valores de 2024-2025. Esta es una infracción distinta a la de no emitir la factura como tal, y ambas pueden aplicarse a la misma empresa dentro de la misma actuación fiscalizadora.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔁 La reincidencia puede significar el cierre del negocio', NULL, NULL, 'El artículo 86 del CNPT prevé el cierre temporal del negocio -- reportado en 5 días -- ante una reincidencia documentada después de una resolución firme anterior. Esta vía de escalamiento implica que una segunda infracción confirmada acarrea una consecuencia sustancialmente distinta a la primera, y no simplemente una multa mayor.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📰 Un operativo real demuestra que esto no es teórico', NULL, NULL, 'En junio de 2024, la DGT visitó cerca de 1.000 negocios en todo el país -- restaurantes, sodas, bares, jugueras, mayoristas de alimentos, licoreras, librerías, bazares y joyerías -- e impuso multas por un total de más de ₡253 millones a 279 contribuyentes, citando el artículo 85 como base legal. El texto exacto de los artículos 85, 85 bis y 86 está bien corroborado en fuentes independientes, incluyendo este reporte del operativo, pero no se extrajo de forma independiente de la base de datos legal oficial de Costa Rica (pgrweb.go.cr) en esta ronda de investigación -- trate los números de artículo y el mecanismo como confiables, y confirme las cifras exactas y vigentes con un asesor fiscal costarricense antes de usarlas para una decisión de cumplimiento específica.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'No emitir o entregar una factura/comprobante electrónico (art. 85 del CNPT)', '2 salarios base (aproximadamente ₡924.400 según los valores 2024-2025); no aplica descuento por corrección voluntaria', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Rechazar medios de pago electrónicos o alternativos cuando su aceptación es obligatoria (art. 85 bis del CNPT)', '1 salario base (aproximadamente ₡462.200 según los valores 2024-2025)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Reincidencia después de una resolución firme anterior (art. 86 del CNPT)', 'Cierre temporal del negocio, reportado en 5 días', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme el dígito de su cédula y cuál ola de 2018 le correspondió', 'El mandato general de Costa Rica se escalonó según el último dígito de la cédula del contribuyente entre setiembre y noviembre de 2018 -- confirme que su empresa ha cumplido desde la fecha de su ola correspondiente, y no solo que conoce el mandato en general.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Inscríbase con una solución certificada de facturación electrónica o con la herramienta gratuita TICO FACTURA de Hacienda', 'Los contribuyentes pequeños pueden usar la herramienta gratuita de Hacienda; las empresas más grandes o de mayor volumen suelen usar un proveedor certificado de terceros integrado a su sistema contable.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que sus sistemas estén certificados contra el esquema XML v4.4', 'El esquema v4.4 se volvió obligatorio el 1 de setiembre de 2025 -- confirme que su software o proveedor realmente implementó los nuevos campos (SINPE Móvil, datos de contribuyentes no domiciliados, documentación de exoneraciones) y no solo pasa la validación básica.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Incorpore el flujo de respuesta del comprador en su proceso de cuentas por pagar', 'Como receptor de facturas B2B, debe aceptar, aceptar parcialmente o rechazar cada una dentro de los 8 días hábiles del mes siguiente -- no cumplir con este plazo puede generar disputas sobre la deducibilidad.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Migre a TRIBU-CR cualquier proceso que todavía dependa de ATV', 'ATV se dio de baja la noche antes del lanzamiento de TRIBU-CR el 6 de octubre de 2025 -- confirme que su equipo trabaja por completo en la nueva plataforma y en TICO FACTURA, en lugar de seguir usando flujos de trabajo desactualizados de ATV.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Prepare desde ya sus sistemas para el formato alfanumérico de cédula jurídica', 'Las sociedades recién inscritas tendrán cédulas como 3-101-A00001 en lugar del formato totalmente numérico actual -- confirme que la lógica de facturación y validación de contrapartes de sus sistemas no tenga codificado un patrón exclusivamente numérico, antes del cambio de producción previsto para el 1 de noviembre de 2026.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Ministerio de Hacienda — API de Comprobantes Electrónicos, la referencia técnica oficial para el envío y la validación de facturas' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Ministerio de Hacienda — Avisos TRIBU-CR, el portal oficial de la nueva plataforma tributaria integrada y las herramientas de facturación electrónica' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pt.sort_order = 1;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Echtzeit-Freigabe über den Dienst Recepción de Comprobantes Electrónicos der DGT -- seit 2018 für praktisch alle mehrwertsteuerpflichtigen Personen verpflichtend, aktuell mitten im Übergang zu Haciendas neuer Plattform TRIBU-CR', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise von Hacienda/DGT und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei Hacienda, der DGT oder einem costa-ricanischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Costa Ricas E-Rechnungssystem geht auf eine erste Regelung von 2007 und ein freiwilliges Pilotprojekt von 2013 zurück, wurde Anfang 2018 für das Gesundheitswesen und andere freiberufliche Sektoren verpflichtend und schloss unter der Resolution DGT-R-012-2018 bis zum 1. November 2018 einen allgemeinen, nach ID-Ziffer gestaffelten Rollout ab. Seither hat Hacienda das System kontinuierlich weiterentwickelt: Das XML-Schema v4.4 wurde im September 2025 verpflichtend, die Plattform TRIBU-CR löste ATV im Oktober 2025 ab, und ein weiterer Wechsel des ID-Formats wird für November 2026 erwartet.', 'Eine konforme Rechnung wird als digital signiertes XML-Dokument erstellt und an die API Recepción de Comprobantes Electrónicos der DGT übermittelt. Die DGT validiert Struktur, Felder und Querverweise des Dokuments -- in der Praxis meist nahezu augenblicklich, mit einem vertraglichen Maximum von 3 Stunden -- und gibt vor der Zustellung an den Empfänger einen Status von akzeptiert oder abgelehnt zurück. Dies ist ein echtes Freigabemodell: Eine von der DGT nicht akzeptierte Rechnung hat keine Rechtswirkung.', 'Die Pflicht besteht in irgendeiner Form seit 2007, erreichte bis November 2018 praktisch alle mehrwertsteuerpflichtigen Personen und entwickelt sich seither technisch weiter, statt sich im Anwendungsbereich auszudehnen -- die aktuelle Änderungswelle (Schema v4.4, die Plattform TRIBU-CR, der bevorstehende Wechsel des ID-Formats) betrifft, wie bereits verpflichtete Unternehmen ihre Rechnungen übermitteln und formatieren, nicht, wer zur Einhaltung verpflichtet ist.', 'Die meisten Unternehmen, die dies lesen, sind wahrscheinlich bereits zur Ausstellung elektronischer Comprobantes verpflichtet -- die eigentliche, aktuelle Aufgabe besteht darin, mit Haciendas laufendem technischen Übergang (Schema v4.4, TRIBU-CR, dem ID-Formatwechsel 2026) Schritt zu halten, nicht in einer erstmaligen Einführung.', 'Costa Rica untermauert seine E-Rechnungspflicht mit realen, artikelspezifischen Sanktionen nach dem Código de Normas y Procedimientos Tributarios (CNPT) -- gekoppelt an den gerichtlich festgelegten Grundlohn (salario base) statt an feste Colón-Beträge --, und die DGT hat gezeigt, dass sie diese auch tatsächlich durchsetzt: Eine einzige Kontrollaktion im Jahr 2024 verhängte gegen 279 Unternehmen Bußgelder von über ₡253 Millionen.', 'Costa Rica verlangt die Echtzeit-Freigabe elektronischer Comprobantes (Rechnungen, Tickets, Gutschriften/Lastschriften und mehr) durch die DGT für praktisch alle mehrwertsteuerlich registrierten Unternehmen, verpflichtend seit 2018. Das System befindet sich derzeit mitten im Übergang: Das XML-Schema v4.4 wurde im September 2025 verpflichtend, Haciendas neue Plattform TRIBU-CR löste ATV im Oktober 2025 ab, und ein weiterer Wechsel zur alphanumerischen Steuerpflichtigen-ID wird für November 2026 erwartet.', '🇨🇷' FROM countries WHERE name_en = 'Costa Rica';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Nov. 2018', 'Allgemeine Pflicht für alle verbleibenden mehrwertsteuerpflichtigen Personen abgeschlossen' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'v4.4', 'Aktuell verpflichtende XML-Schema-Version, seit 1. September 2025' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '6. Okt. 2025', 'Haciendas neue Plattform TRIBU-CR löst ATV ab' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '₡253 Mio.+', 'Bußgelder gegen 279 Steuerpflichtige in einer einzigen DGT-Kontrollaktion 2024' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '≤3 Std.', 'Maximale SLA-Reaktionszeit der DGT für die Rechnungsvalidierung' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Validierung', '[["Rechnungsformat", "Signiertes XML, Costa Ricas eigenes Schema (nicht UBL/PEPPOL)"], ["Validierungsmodell", "Freigabe -- die DGT muss das Dokument akzeptieren, bevor es steuerlich gültig ist"], ["Übermittlung", "POST an die API Recepción de Comprobantes Electrónicos der DGT (OIDC/OAuth 2.0, base64-kodiertes XML)"], ["Antwortzeit", "In der Praxis meist nahezu augenblicklich; Haciendas eigene technische Resolution setzt ein Maximum von 3 Stunden fest"], ["Digitale Signatur", "XAdES EPES v1.3.2 oder höher, mit einem .p12-Zertifikat der Zertifizierungsstelle der Zentralbank (BCCR)"]]', 'Anbieter-Marketing beschreibt dies mitunter als reine „Echtzeit"-Validierung -- das trifft in der Praxis meist zu, doch das verbindliche SLA in Haciendas eigener technischer Resolution ist ein Maximum von 3 Stunden, keine sofortige Garantie.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Belegtypen', '[["01 — Factura Electrónica", "Standard-B2B-Verkauf / Verkauf an identifizierten Käufer"], ["02 / 03 — Nota de Débito / Crédito", "Anpassungen, Rückgaben, Rabatte, Stornierungen"], ["04 — Tiquete Electrónico", "Einzelhandelsverkauf an einen nicht identifizierten Endverbraucher (B2C)"], ["08 — Factura Electrónica de Compra", "Vom Käufer ausgestellter Beleg beim Einkauf von einem informellen, nicht rechnungsstellenden Lieferanten"], ["09 — Factura Electrónica de Exportación", "Exportverkäufe mit 0 % Mehrwertsteuer"]]', 'Mit Schema v4.4 kam der Recibo Electrónico de Pago (Zahlungsbeleg) als weiterer Belegtyp hinzu -- prüfen Sie, ob Ihre Software ihn dort ausstellt, wo er erforderlich ist, statt anzunehmen, dass die fünf oben genannten Kerntypen die vollständige Liste sind.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Clave numérica, Käuferantwort und Aufbewahrung', '[["Clave numérica", "Ein vom System des Ausstellers automatisch generierter 50-stelliger Schlüssel, der Ausstellungsdatum, Aussteller-ID, Belegtyp, fortlaufende Nummer und einen Sicherheitscode kodiert"], ["Käuferantwort (B2B)", "Der Empfänger muss den Beleg innerhalb von 8 Werktagen des Folgemonats akzeptieren, teilweise akzeptieren oder ablehnen"], ["Kontingenzmodus", "Belege können bis zu 48 Stunden nach Wiederherstellung des Dienstes eingereicht werden, falls die Systeme von Hacienda ausfallen"], ["Aufbewahrung", "5 Jahre"]]', 'Der genaue, ziffernweise Aufbau der 50-stelligen clave numérica variiert leicht je nach Sekundärquelle -- die Gesamtlänge (50 Ziffern) und der allgemeine Inhalt gelten als zuverlässig, verlassen Sie sich aber nicht auf eine positionsgenaue Aufschlüsselung, ohne diese mit Haciendas aktuellem technischen Anhang abzugleichen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Freigabeablauf', 'Ein konformer Comprobante Electrónico durchläuft folgende Abfolge:', 'Nur ein akzeptiertes (aceptado) Dokument ist ein gültiger Steuerbeleg -- eine von der DGT nicht akzeptierte Rechnung hat keine Rechtswirkung, und eine vom Empfänger ordnungsgemäß abgelehnte Rechnung stützt dessen Vorsteuerabzug nicht.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der Aussteller erstellt mit einem zugelassenen Zertifikat ein digital signiertes XML' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Das Dokument wird an die API Recepción de Comprobantes Electrónicos der DGT übermittelt' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die DGT validiert Struktur, Felder und Querverweise (in der Praxis nahezu augenblicklich; vertraglich bis zu 3 Stunden)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die DGT gibt einen Status von aceptado oder rechazado zurück' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Das akzeptierte Dokument wird an den Empfänger zugestellt, der innerhalb von 8 Werktagen des Folgemonats antworten muss' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Was das Gesetz verlangt', '[["DGT-R-012-2018 (2018)", "Die allgemeine Pflicht, gestaffelt nach der letzten Ziffer der Steuerpflichtigen-ID"], ["Ley 7092 (Einkommensteuergesetz), Art. 3", "Rechtsgrundlage für die eng begrenzte Ausnahme für den öffentlichen Sektor/gemeinnützige Einrichtungen"], ["Régimen Simplificado", "Von der allgemeinen Pflicht ausdrücklich ausgenommen"], ["Keine Umsatzschwelle", "Die Pflicht gilt universell für mehrwertsteuerlich registrierte Personen außerhalb der aufgeführten Ausnahmen"]]', 'Sobald ein Steuerpflichtiger in den Anwendungsbereich fällt, sind B2B-, B2C- (über den Tiquete Electrónico) und B2G-Transaktionen gleichermaßen erfasst -- es handelt sich nicht um ein reines B2G- oder B2B-Regime.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer weiterhin ausgenommen ist', '[["Beitragszahler des Régimen Simplificado", "Unter der DGT-R-012-2018 ausdrücklich ausgenommen"], ["Öffentlicher Sektor / gemeinnützige Einrichtungen", "Nur für nicht-kommerzielle Tätigkeiten -- Gemeinden, Ministerien, öffentliche Universitäten, CCSS, Zentralbank, Justiz, Gesetzgebende Versammlung"], ["Berufskammern (colegios profesionales)", "Nur für die Erhebung von Mitgliedsbeiträgen"], ["Wohnanlagen (Condominios)", "Nur für Instandhaltungsgebühren der Gemeinschaftsflächen"], ["Von der SUGEF regulierte Banken/Genossenschaften und Solidaritätsvereinigungen", "Nur für bestimmte nicht besteuerte Tätigkeiten"]]', 'Jedes gewerbliche oder mehrwertsteuerpflichtige Einkommen dieser gleichen Einrichtungen erfordert weiterhin E-Rechnungen -- die Ausnahme bezieht sich auf die Tätigkeit, nicht auf eine pauschale Befreiung der gesamten Organisation.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Das Nicht-Ausstellen oder Nicht-Zustellen einer Rechnung zieht die höchste Strafe nach sich', NULL, NULL, 'Nach Artikel 85 des CNPT (Código de Normas y Procedimientos Tributarios) zieht das Nicht-Ausstellen oder Nicht-Zustellen einer elektronischen Rechnung oder eines Belegs ein Bußgeld von 2 Grundlöhnen nach sich -- bei den Grundlohnwerten 2024-2025 rund ₡924.400 -- ohne Nachlassmöglichkeit durch Selbstkorrektur für diesen speziellen Verstoß. Costa-ricanische Steuerstrafen dieser Art sind an den gerichtlich festgelegten Referenzwert "salario base" gekoppelt und nicht an einen festen Colón-Betrag, sodass sich der genaue Betrag mit dem jährlich aktualisierten Grundlohn ändert.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💳 Die Ablehnung elektronischer oder alternativer Zahlungen hat eine eigene Strafe', NULL, NULL, 'Artikel 85 bis des CNPT sanktioniert gesondert die Ablehnung elektronischer oder alternativer Zahlungsmittel (etwa Kartenzahlungen oder SINPE), wenn deren Annahme vorgeschrieben ist, mit einem Bußgeld von 1 Grundlohn -- bei den Werten von 2024-2025 rund ₡462.200. Dies ist ein eigenständiger Verstoß, unabhängig vom Nicht-Ausstellen der Rechnung selbst, und beide können im selben Vollzugsverfahren auf dasselbe Unternehmen angewendet werden.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔁 Wiederholungsverstöße können zur Betriebsschließung führen', NULL, NULL, 'Artikel 86 des CNPT sieht bei einem dokumentierten Wiederholungsverstoß nach einer vorangegangenen rechtskräftigen Entscheidung eine vorübergehende Betriebsschließung vor -- berichtet mit 5 Tagen. Dieser Eskalationspfad bedeutet, dass ein zweiter bestätigter Verstoß eine wesentlich andere Folge nach sich zieht als ein erster -- nicht nur ein höheres Bußgeld.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📰 Eine reale Kontrollaktion zeigt: Das ist nicht nur Theorie', NULL, NULL, 'Im Juni 2024 besuchte die DGT landesweit fast 1.000 Betriebe -- Restaurants, Sodas (kleine Imbisse), Bars, Saftverkäufer, Lebensmittelgroßhändler, Spirituosengeschäfte, Buchhandlungen, Basare und Juweliere -- und verhängte gegen 279 Steuerpflichtige Bußgelder in Höhe von insgesamt über ₡253 Millionen, wobei Artikel 85 als Rechtsgrundlage genannt wurde. Der genaue Gesetzestext der Artikel 85, 85 bis und 86 ist durch unabhängige Quellen, einschließlich dieses Berichts über die Kontrollaktion, gut belegt, wurde in dieser Rechercherunde jedoch nicht eigenständig aus Costa Ricas offizieller Rechtsdatenbank (pgrweb.go.cr) abgerufen -- betrachten Sie die Artikelnummern und den Mechanismus als zuverlässig, und bestätigen Sie die genauen aktuellen Beträge mit einem costa-ricanischen Steuerberater, bevor Sie sich für eine konkrete Compliance-Entscheidung darauf stützen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Nicht-Ausstellung oder Nicht-Zustellung einer elektronischen Rechnung/eines Belegs (Art. 85 CNPT)', '2 Grundlöhne (bei den Werten 2024-2025 rund ₡924.400); kein Nachlass durch Selbstkorrektur möglich', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Ablehnung elektronischer oder alternativer Zahlungsmittel bei vorgeschriebener Annahme (Art. 85 bis CNPT)', '1 Grundlohn (bei den Werten 2024-2025 rund ₡462.200)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Wiederholungsverstoß nach vorangegangener rechtskräftiger Entscheidung (Art. 86 CNPT)', 'Vorübergehende Betriebsschließung, berichtet mit 5 Tagen', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie die Ziffer Ihrer Steuerpflichtigen-ID und welche Welle von 2018 für Sie galt', 'Costa Ricas allgemeine Pflicht wurde zwischen September und November 2018 nach der letzten Ziffer der Steuerpflichtigen-ID gestaffelt -- prüfen Sie, ob Ihr Unternehmen seit seiner Welle konform ist, nicht nur, dass Sie die Pflicht allgemein kennen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Registrieren Sie sich bei einer zertifizierten E-Rechnungslösung oder bei Haciendas kostenlosem Tool TICO FACTURA', 'Kleine Steuerpflichtige können Haciendas eigenes kostenloses Tool nutzen; größere oder umsatzstärkere Unternehmen verwenden in der Regel einen zertifizierten Drittanbieter, der in ihr Buchhaltungssystem integriert ist.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Ihre Systeme für das XML-Schema v4.4 zertifiziert sind', 'Schema v4.4 wurde am 1. September 2025 verpflichtend -- prüfen Sie, ob Ihre Software oder Ihr Anbieter die neuen Felder (SINPE Móvil, Daten nicht ansässiger Steuerpflichtiger, Befreiungsdokumentation) tatsächlich implementiert hat, statt nur die Basisvalidierung zu bestehen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Integrieren Sie den Käuferantwort-Workflow in Ihren Kreditorenprozess', 'Als Empfänger von B2B-Rechnungen müssen Sie jede einzelne innerhalb von 8 Werktagen des Folgemonats akzeptieren, teilweise akzeptieren oder ablehnen -- eine versäumte Frist kann zu Streitigkeiten über die Abzugsfähigkeit führen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Migrieren Sie verbleibende ATV-basierte Prozesse zu TRIBU-CR', 'ATV wurde am Vorabend des Starts von TRIBU-CR am 6. Oktober 2025 abgeschaltet -- stellen Sie sicher, dass Ihr Team vollständig auf der neuen Plattform und mit TICO FACTURA arbeitet, statt sich auf veraltete ATV-Workflows zu beziehen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bereiten Sie Ihre Systeme jetzt auf das alphanumerische cédula-jurídica-Format vor', 'Neu registrierte Unternehmen erhalten IDs wie 3-101-A00001 statt des aktuellen rein numerischen Formats -- prüfen Sie, dass Ihre Rechnungs- und Gegenparteivalidierungslogik kein rein numerisches Muster fest codiert, bevor der erwartete Produktions-Stichtag am 1. November 2026 erreicht ist.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Ministerio de Hacienda — API der Comprobantes Electrónicos, die offizielle technische Referenz für die Übermittlung und Validierung von Rechnungen' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Ministerio de Hacienda — Avisos TRIBU-CR, das offizielle Portal für die neue integrierte Steuerplattform und die E-Rechnungstools' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pt.sort_order = 1;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Dédouanement en temps réel via le service Recepción de Comprobantes Electrónicos de la DGT -- obligatoire pour la quasi-totalité des contribuables à la TVA depuis 2018, et actuellement en pleine transition vers la nouvelle plateforme TRIBU-CR de Hacienda', 'Cette page d''analyse reflète les indications publiques de Hacienda/DGT et les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès de Hacienda, de la DGT ou d''un conseiller fiscal costaricien avant de fonder vos décisions de conformité sur cette page.', 'Le régime de facturation électronique du Costa Rica remonte à une première réglementation de 2007 et à un projet pilote volontaire de 2013, est devenu obligatoire pour le secteur de la santé et d''autres professions libérales début 2018, et a achevé un déploiement général échelonné selon le chiffre d''identification, en vertu de la résolution DGT-R-012-2018, le 1er novembre 2018. Depuis, Hacienda a continué de faire évoluer le système : le schéma XML v4.4 est devenu obligatoire en septembre 2025, la plateforme TRIBU-CR a remplacé ATV en octobre 2025, et un nouveau changement de format d''identifiant est attendu en novembre 2026.', 'Une facture conforme est générée sous forme de document XML signé numériquement et soumise à l''API Recepción de Comprobantes Electrónicos de la DGT. La DGT valide la structure, les champs et les recoupements du document -- en pratique, généralement de façon quasi instantanée, avec un maximum contractuel de 3 heures -- et renvoie un statut accepté ou rejeté avant que le document ne soit remis au destinataire. Il s''agit d''un véritable modèle de dédouanement : une facture que la DGT n''a pas acceptée n''a aucun effet juridique.', 'L''obligation existe sous une forme ou une autre depuis 2007, a atteint la quasi-totalité des contribuables à la TVA d''ici novembre 2018, et continue d''évoluer sur le plan technique plutôt que de s''étendre en champ d''application -- la vague de changements actuelle (schéma v4.4, plateforme TRIBU-CR, prochain changement de format d''identifiant) concerne la manière dont les entreprises déjà assujetties transmettent et mettent en forme leurs factures, non l''identité des personnes tenues de s''y conformer.', 'La plupart des entreprises qui lisent cette page sont probablement déjà tenues d''émettre des Comprobantes électroniques -- le travail réel et actuel consiste à suivre le rythme de la transition technique en cours chez Hacienda (schéma v4.4, TRIBU-CR, le changement de format d''identifiant de 2026), et non à effectuer un premier déploiement.', 'Le Costa Rica appuie son obligation de facturation électronique sur des sanctions réelles, propres à chaque article, prévues par le Código de Normas y Procedimientos Tributarios (CNPT) -- indexées sur le salaire de base fixé par voie judiciaire plutôt que sur des montants fixes en colones -- et la DGT a démontré qu''elle les applique réellement : une seule opération menée en 2024 a infligé des amendes à 279 entreprises pour un total de plus de 253 millions de ₡.', 'Le Costa Rica exige le dédouanement en temps réel par la DGT des Comprobantes électroniques (factures, tickets, notes de crédit/débit et autres) pour la quasi-totalité des entreprises assujetties à la TVA, obligation en vigueur depuis 2018. Le système est actuellement en pleine transition : le schéma XML v4.4 est devenu obligatoire en septembre 2025, la nouvelle plateforme TRIBU-CR de Hacienda a remplacé ATV en octobre 2025, et un nouveau changement vers un identifiant de contribuable alphanumérique est attendu en novembre 2026.', '🇨🇷' FROM countries WHERE name_en = 'Costa Rica';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er nov. 2018', 'Achèvement de l''obligation générale pour tous les contribuables à la TVA restants' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'v4.4', 'Version actuellement obligatoire du schéma XML, depuis le 1er septembre 2025' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '6 oct. 2025', 'La nouvelle plateforme TRIBU-CR de Hacienda remplace ATV' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '253 M ₡+', 'Amendes infligées à 279 contribuables lors d''une seule opération de contrôle de la DGT en 2024' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '≤3 h', 'Délai de réponse maximal (SLA) de la DGT pour la validation des factures' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Costa Rica' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et validation', '[["Format de facture", "XML signé, schéma propre au Costa Rica (pas UBL/PEPPOL)"], ["Modèle de validation", "Dédouanement -- la DGT doit accepter le document avant qu''il soit fiscalement valable"], ["Soumission", "POST vers l''API Recepción de Comprobantes Electrónicos de la DGT (OIDC/OAuth 2.0, XML encodé en base64)"], ["Délai de réponse", "En pratique, généralement quasi instantané ; la résolution technique de la DGT elle-même fixe un maximum de 3 heures"], ["Signature numérique", "XAdES EPES v1.3.2 ou supérieur, à l''aide d''un certificat .p12 délivré par l''autorité de certification de la Banque centrale (BCCR)"]]', 'Le marketing de certains fournisseurs présente parfois cela comme une validation purement « en temps réel » -- c''est généralement exact en pratique, mais le SLA contraignant fixé par la propre résolution technique de la DGT est un maximum de 3 heures, non une garantie instantanée.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Types de documents', '[["01 — Factura Electrónica", "Vente standard B2B / à acheteur identifié"], ["02 / 03 — Nota de Débito / Crédito", "Ajustements, retours, remises, annulations"], ["04 — Tiquete Electrónico", "Vente au détail à un consommateur final non identifié (B2C)"], ["08 — Factura Electrónica de Compra", "Document émis par l''acheteur lors d''un achat auprès d''un fournisseur informel n''émettant pas de factures"], ["09 — Factura Electrónica de Exportación", "Ventes à l''exportation à 0 % de TVA"]]', 'Un Recibo Electrónico de Pago (reçu de paiement) a été ajouté comme type de document supplémentaire avec le schéma v4.4 -- vérifiez que votre logiciel l''émet lorsque requis, plutôt que de présumer que les cinq types principaux ci-dessus constituent la liste complète.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Clave numérica, réponse de l''acheteur et conservation', '[["Clave numérica", "Une clé à 50 chiffres, générée automatiquement par le système de l''émetteur, codant la date d''émission, l''identifiant de l''émetteur, le type de document, le numéro consécutif et un code de sécurité"], ["Réponse de l''acheteur (B2B)", "Le destinataire doit accepter, accepter partiellement ou rejeter le document dans les 8 jours ouvrables du mois suivant"], ["Mode de contingence", "Les documents peuvent être soumis jusqu''à 48 heures après le rétablissement du service si les systèmes de Hacienda sont hors service"], ["Conservation", "5 ans"]]', 'La composition exacte, chiffre par chiffre, de la clave numérica à 50 chiffres varie légèrement selon les sources secondaires -- la longueur totale (50 chiffres) et le contenu général peuvent être considérés comme fiables, mais ne vous fiez pas à une répartition précise position par position sans la confirmer auprès de l''annexe technique actuelle de Hacienda.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de dédouanement', 'Un Comprobante Electrónico conforme suit cette séquence :', 'Seul un document accepté (aceptado) constitue un justificatif fiscal valable -- une facture que la DGT n''a pas acceptée n''a aucun effet juridique, et une facture correctement rejetée par le destinataire ne peut justifier sa déduction.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'L''émetteur génère un XML signé numériquement à l''aide d''un certificat agréé' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le document est soumis à l''API Recepción de Comprobantes Electrónicos de la DGT' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La DGT valide la structure, les champs et les recoupements (quasi instantané en pratique ; jusqu''à 3 heures contractuellement)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La DGT renvoie un statut accepté (aceptado) ou rejeté (rechazado)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le document accepté est remis au destinataire, qui doit répondre dans les 8 jours ouvrables du mois suivant' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Costa Rica' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Ce que la loi exige', '[["DGT-R-012-2018 (2018)", "L''obligation générale, échelonnée selon le dernier chiffre du numéro d''identification du contribuable"], ["Ley 7092 (loi sur l''impôt sur le revenu), art. 3", "Base légale de l''exemption restreinte pour le secteur public et les organismes à but non lucratif"], ["Régimen Simplificado", "Exclu d''office de l''obligation générale"], ["Aucun seuil de chiffre d''affaires", "L''obligation est universelle pour les contribuables assujettis à la TVA en dehors des exceptions listées"]]', 'Dès qu''un contribuable entre dans le champ d''application, les transactions B2B, B2C (via le Tiquete Electrónico) et B2G sont toutes couvertes -- il ne s''agit pas d''un régime exclusivement B2G ou B2B.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui reste exempté', '[["Contribuables du Régimen Simplificado", "Exclus d''office en vertu de la DGT-R-012-2018"], ["Organismes du secteur public / à but non lucratif", "Pour leur seule activité non commerciale -- municipalités, ministères, universités publiques, CCSS, Banque centrale, pouvoir judiciaire, Assemblée législative"], ["Ordres professionnels (colegios profesionales)", "Pour la seule perception des cotisations"], ["Copropriétés", "Pour les seules charges d''entretien des parties communes"], ["Banques/coopératives réglementées par la SUGEF et associations solidaristes", "Pour certaines activités non imposées uniquement"]]', 'Tout revenu commercial ou soumis à la TVA perçu par ces mêmes entités continue de nécessiter la facturation électronique -- l''exemption est propre à l''activité, et non une exonération globale pour l''organisme.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ Ne pas émettre ou remettre une facture entraîne l''amende la plus lourde', NULL, NULL, 'En vertu de l''article 85 du CNPT (Código de Normas y Procedimientos Tributarios), le fait de ne pas émettre ou de ne pas remettre une facture ou un comprobante électronique entraîne une amende de 2 salaires de base -- soit environ 924 400 ₡ selon les valeurs du salaire de base 2024-2025 -- sans possibilité de réduction pour autocorrection pour cette infraction précise. Les amendes fiscales costariciennes de ce type sont indexées sur le montant de référence « salario base » fixé par voie judiciaire plutôt que sur un montant fixe en colones ; le montant exact varie donc avec le salaire de base mis à jour chaque année.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💳 Le refus d''un paiement électronique ou alternatif fait l''objet de sa propre sanction', NULL, NULL, 'L''article 85 bis du CNPT sanctionne séparément le refus d''accepter des moyens de paiement électroniques ou alternatifs (tels que les paiements par carte ou SINPE) lorsque leur acceptation est requise, par une amende de 1 salaire de base -- soit environ 462 200 ₡ selon les valeurs 2024-2025. Il s''agit d''une infraction distincte du défaut d''émission de la facture elle-même, et les deux peuvent s''appliquer à la même entreprise dans le cadre d''une même action de contrôle.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔁 La récidive peut entraîner la fermeture de l''entreprise', NULL, NULL, 'L''article 86 du CNPT prévoit la fermeture temporaire de l''établissement -- signalée à 5 jours -- en cas de récidive documentée après une résolution ferme antérieure. Cette voie d''escalade signifie qu''une seconde infraction confirmée entraîne une conséquence sensiblement différente de la première, et non une simple amende plus élevée.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📰 Une opération de contrôle réelle montre que ce n''est pas de la théorie', NULL, NULL, 'En juin 2024, la DGT a visité près de 1 000 entreprises dans tout le pays -- restaurants, « sodas » (petits restaurants), bars, vendeurs de jus, grossistes alimentaires, magasins de spiritueux, librairies, bazars et bijouteries -- et a infligé des amendes totalisant plus de 253 millions de ₡ à 279 contribuables, en citant l''article 85 comme base légale. Le texte exact des articles 85, 85 bis et 86 est bien corroboré par des sources indépendantes, y compris ce rapport sur l''opération de contrôle, mais n''a pas pu être extrait de manière indépendante de la base de données juridique officielle du Costa Rica (pgrweb.go.cr) au cours de cette phase de recherche -- considérez les numéros d''articles et le mécanisme comme fiables, et confirmez les montants exacts actuels auprès d''un conseiller fiscal costaricien avant de vous en servir pour une décision de conformité précise.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Costa Rica' AND cd.section = 'penalties_related' AND cd.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Défaut d''émission ou de remise d''une facture/d''un comprobante électronique (art. 85 du CNPT)', '2 salaires de base (environ 924 400 ₡ selon les valeurs 2024-2025) ; aucune réduction pour autocorrection applicable', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Refus d''accepter des moyens de paiement électroniques ou alternatifs lorsque requis (art. 85 bis du CNPT)', '1 salaire de base (environ 462 200 ₡ selon les valeurs 2024-2025)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Récidive après une résolution ferme antérieure (art. 86 du CNPT)', 'Fermeture temporaire de l''entreprise, signalée à 5 jours', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pr.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez le chiffre de votre numéro d''identification et quelle vague de 2018 s''appliquait à vous', 'L''obligation générale du Costa Rica a été échelonnée selon le dernier chiffre du numéro d''identification du contribuable entre septembre et novembre 2018 -- vérifiez que votre entreprise est conforme depuis sa vague, et pas seulement qu''elle a connaissance de l''obligation en général.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Inscrivez-vous auprès d''une solution de facturation électronique certifiée ou de l''outil gratuit TICO FACTURA de Hacienda', 'Les petits contribuables peuvent utiliser l''outil gratuit de Hacienda ; les entreprises plus grandes ou à volume plus élevé recourent généralement à un prestataire tiers certifié intégré à leur système comptable.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que vos systèmes sont certifiés pour le schéma XML v4.4', 'Le schéma v4.4 est devenu obligatoire le 1er septembre 2025 -- vérifiez que votre logiciel ou votre prestataire a réellement mis en œuvre les nouveaux champs (SINPE Móvil, données des contribuables non domiciliés, documentation d''exonération), et non simplement réussi la validation de base.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Intégrez le flux de réponse de l''acheteur dans votre processus de comptes fournisseurs', 'En tant que destinataire de factures B2B, vous devez accepter, accepter partiellement ou rejeter chacune d''elles dans les 8 jours ouvrables du mois suivant -- un dépassement de ce délai peut créer des litiges sur la déductibilité.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Migrez tout processus encore basé sur ATV vers TRIBU-CR', 'ATV a été retiré la veille au soir du lancement de TRIBU-CR, le 6 octobre 2025 -- vérifiez que votre équipe travaille entièrement sur la nouvelle plateforme et sur TICO FACTURA, plutôt que de continuer à se référer à d''anciens flux de travail ATV.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Préparez dès maintenant vos systèmes au format alphanumérique de la cédula jurídica', 'Les sociétés nouvellement immatriculées porteront des identifiants tels que 3-101-A00001 au lieu de l''actuel format entièrement numérique -- vérifiez que la logique de facturation et de validation des contreparties de vos systèmes ne code pas en dur un format purement numérique, avant l''échéance de bascule en production prévue le 1er novembre 2026.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Costa Rica' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Ministerio de Hacienda — API Comprobantes Electrónicos, la référence technique officielle pour la soumission et la validation des factures' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Ministerio de Hacienda — Avisos TRIBU-CR, le portail officiel de la nouvelle plateforme fiscale intégrée et des outils de facturation électronique' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Costa Rica' AND pt.sort_order = 1;
